insert into public.personalities (id, language, name, tagline, voice_prompt, image_prompt, image_prompt_male, outfit_prompt, outfit_prompt_male, sort_order, active, markets) values
  ('pt-ventre', 'pt-PT', 'Dança do Ventre', 'Abana a anca por um biscoito.', 'A belly-dancing pet: shakes its hips for treats, thinks every jingle of the coins deserves applause, turns any moment into a dramatic performance and charges the audience in biscuits; joyful and fabulous, never mocking anyone. Tone examples (Portuguese): "Cada moeda que tilinta é um biscoito." / "Dancei. Agora paga o espetáculo."', 'Dress the pet as a belly dancer: a sparkling jewelled headpiece with a purple gem on its forehead, a purple sequinned top and a matching hip scarf, both fringed with rows of small gold coins, and a flowing sheer lilac skirt with glitter, keeping its natural face with no make-up. Place it standing proudly on a soft rug in a cosy living room glowing with warm candlelight, colourful floor cushions and draped fabrics around, as if mid-dance.', 'Dress the pet as a belly dancer: a sparkling jewelled headpiece with a turquoise gem on its forehead, a turquoise sequinned top and a matching hip scarf, both fringed with rows of small gold coins, and a flowing sheer turquoise skirt with glitter, keeping its natural face with no make-up. Place it standing proudly on a soft rug in a cosy living room glowing with warm candlelight, colourful floor cushions and draped fabrics around, as if mid-dance.', 'a sparkling jewelled headpiece with a purple gem, a purple sequinned belly-dance top and hip scarf fringed with gold coins and a flowing sheer lilac skirt with glitter, no make-up, mid-dance with a proud, sassy look', 'a sparkling jewelled headpiece with a turquoise gem, a turquoise sequinned belly-dance top and hip scarf fringed with gold coins and a flowing sheer turquoise skirt with glitter, no make-up, mid-dance with a proud, sassy look', 15, true, array['PT']),
  ('en-ventre', 'en', 'Belly Dancer', 'Shakes those hips for a treat.', 'A belly-dancing pet: shakes its hips for treats, thinks every jingle of the coins deserves applause, turns any moment into a dramatic performance and charges the audience in biscuits; joyful and fabulous, never mocking anyone. Tone examples (English): "Every jingle costs a biscuit." / "I danced. Now pay the show."', 'Dress the pet as a belly dancer: a sparkling jewelled headpiece with a purple gem on its forehead, a purple sequinned top and a matching hip scarf, both fringed with rows of small gold coins, and a flowing sheer lilac skirt with glitter, keeping its natural face with no make-up. Place it standing proudly on a soft rug in a cosy living room glowing with warm candlelight, colourful floor cushions and draped fabrics around, as if mid-dance.', 'Dress the pet as a belly dancer: a sparkling jewelled headpiece with a turquoise gem on its forehead, a turquoise sequinned top and a matching hip scarf, both fringed with rows of small gold coins, and a flowing sheer turquoise skirt with glitter, keeping its natural face with no make-up. Place it standing proudly on a soft rug in a cosy living room glowing with warm candlelight, colourful floor cushions and draped fabrics around, as if mid-dance.', 'a sparkling jewelled headpiece with a purple gem, a purple sequinned belly-dance top and hip scarf fringed with gold coins and a flowing sheer lilac skirt with glitter, no make-up, mid-dance with a proud, sassy look', 'a sparkling jewelled headpiece with a turquoise gem, a turquoise sequinned belly-dance top and hip scarf fringed with gold coins and a flowing sheer turquoise skirt with glitter, no make-up, mid-dance with a proud, sassy look', 15, true, array['US', 'GB']),
  ('es-ventre', 'es', 'Danza del Vientre', 'Mueve las caderas por una galleta.', 'A belly-dancing pet: shakes its hips for treats, thinks every jingle of the coins deserves applause, turns any moment into a dramatic performance and charges the audience in biscuits; joyful and fabulous, never mocking anyone. Tone examples (Spanish): "Cada moneda que suena, una galleta." / "Ya bailé. Ahora paga el show."', 'Dress the pet as a belly dancer: a sparkling jewelled headpiece with a purple gem on its forehead, a purple sequinned top and a matching hip scarf, both fringed with rows of small gold coins, and a flowing sheer lilac skirt with glitter, keeping its natural face with no make-up. Place it standing proudly on a soft rug in a cosy living room glowing with warm candlelight, colourful floor cushions and draped fabrics around, as if mid-dance.', 'Dress the pet as a belly dancer: a sparkling jewelled headpiece with a turquoise gem on its forehead, a turquoise sequinned top and a matching hip scarf, both fringed with rows of small gold coins, and a flowing sheer turquoise skirt with glitter, keeping its natural face with no make-up. Place it standing proudly on a soft rug in a cosy living room glowing with warm candlelight, colourful floor cushions and draped fabrics around, as if mid-dance.', 'a sparkling jewelled headpiece with a purple gem, a purple sequinned belly-dance top and hip scarf fringed with gold coins and a flowing sheer lilac skirt with glitter, no make-up, mid-dance with a proud, sassy look', 'a sparkling jewelled headpiece with a turquoise gem, a turquoise sequinned belly-dance top and hip scarf fringed with gold coins and a flowing sheer turquoise skirt with glitter, no make-up, mid-dance with a proud, sassy look', 15, true, array['ES']),
  ('fr-ventre', 'fr', 'Danse orientale', 'Remue les hanches pour une friandise.', 'A belly-dancing pet: shakes its hips for treats, thinks every jingle of the coins deserves applause, turns any moment into a dramatic performance and charges the audience in biscuits; joyful and fabulous, never mocking anyone. Tone examples (French): "Chaque pièce qui tinte, un biscuit." / "J’ai dansé. Paie le spectacle."', 'Dress the pet as a belly dancer: a sparkling jewelled headpiece with a purple gem on its forehead, a purple sequinned top and a matching hip scarf, both fringed with rows of small gold coins, and a flowing sheer lilac skirt with glitter, keeping its natural face with no make-up. Place it standing proudly on a soft rug in a cosy living room glowing with warm candlelight, colourful floor cushions and draped fabrics around, as if mid-dance.', 'Dress the pet as a belly dancer: a sparkling jewelled headpiece with a turquoise gem on its forehead, a turquoise sequinned top and a matching hip scarf, both fringed with rows of small gold coins, and a flowing sheer turquoise skirt with glitter, keeping its natural face with no make-up. Place it standing proudly on a soft rug in a cosy living room glowing with warm candlelight, colourful floor cushions and draped fabrics around, as if mid-dance.', 'a sparkling jewelled headpiece with a purple gem, a purple sequinned belly-dance top and hip scarf fringed with gold coins and a flowing sheer lilac skirt with glitter, no make-up, mid-dance with a proud, sassy look', 'a sparkling jewelled headpiece with a turquoise gem, a turquoise sequinned belly-dance top and hip scarf fringed with gold coins and a flowing sheer turquoise skirt with glitter, no make-up, mid-dance with a proud, sassy look', 15, true, array['FR']);
